          {"id": "card", "label": "Captain approves", "lane": 0, "kind": "step", "state": "same"},
          {"id": "plan", "label": "Worker reads and plans", "lane": 2, "kind": "focal", "state": "new", "change": "c2"},
          {"id": "build", "label": "Worker builds", "lane": 2, "kind": "step", "state": "same"}
        ],
