          {"id": "card", "label": "船長核可", "lane": 0, "kind": "step", "state": "same"},
          {"id": "plan", "label": "worker 讀程式並計畫", "lane": 2, "kind": "focal", "state": "new", "change": "c2"},
          {"id": "build", "label": "worker 實作", "lane": 2, "kind": "step", "state": "same"}
